<script lang="ts">
	import { onMount } from 'svelte';
	import { hasBingo, shuffle } from '#lib/bingo.js';
	import { celebrate, loadConfetti } from '#lib/confetti.js';

	const LABELS = [
		'„Hallo? Halloooo?“',
		'„Sind alle da?“',
		'„Sorry, mein Akku war leer...“',
		'„Versteht ihr mich?“',
		'„Mein WLAN spinnt!“',
		'Rückkopplung, Pfeifen, ...',
		'Kinderstimmen',
		'„Ich muss in die nächste Telko!“',
		'Schwarze Silhouette vor Fenster',
		'Tiergeräusche',
		'„Ich musste kurz ein Paket annehmen“',
		'Verpixeltes Bild / gar kein Bild',
		'Lautes Tastatur-Tippen',
		'...alle reden gleichzeitig.',
		'Klospülung',
		'Partner läuft durchs Bild'
	];
	const SPEAKER = 3;
	const CAT = 9;

	let order = $state(LABELS.map((_, label) => label));
	let marked = $state(LABELS.map(() => false));
	let textVisible = $state(false);
	const won = $derived(hasBingo(marked));

	// The prerendered order stays hidden until the browser has shuffled it.
	onMount(() => {
		order = shuffle(order);
		textVisible = true;
		void loadConfetti();
	});

	$effect(() => {
		if (won) return celebrate();
	});
</script>

